"use client"

import { useEffect, useRef, useState } from "react"
import Image from "next/image"
import Link from "next/link"
import { cn } from "@/lib/utils"

const projects = [
  {
    title: "Casa Monteverde",
    category: "Residences",
    image: "/images/project-1.jpg",
    href: "/portfolio/residences",
  },
  {
    title: "Nosara Wellness Retreat",
    category: "Resorts",
    image: "/images/project-2.jpg",
    href: "/portfolio/resorts",
  },
  {
    title: "Peninsula Yoga Shala",
    category: "Conceptual",
    image: "/images/project-3.jpg",
    href: "/portfolio/conceptual",
  },
  {
    title: "Rainforest Pavilion",
    category: "Residences",
    image: "/images/project-4.jpg",
    href: "/portfolio/residences",
  },
]

export function Gallery() {
  const [isVisible, setIsVisible] = useState(false)
  const sectionRef = useRef<HTMLElement>(null)

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true)
          observer.disconnect()
        }
      },
      { threshold: 0.1 }
    )

    if (sectionRef.current) {
      observer.observe(sectionRef.current)
    }

    return () => observer.disconnect()
  }, [])

  return (
    <section
      ref={sectionRef}
      id="portfolio"
      className="bg-background py-24 md:py-32"
    >
      <div className="mx-auto max-w-7xl px-6 lg:px-8">
        <div className="flex flex-col items-start justify-between gap-4 md:flex-row md:items-end">
          <div>
            <span
              className={cn(
                "text-xs tracking-widest text-muted-foreground uppercase opacity-0",
                isVisible && "animate-fade-in-up"
              )}
            >
              Our Work
            </span>
            <h2
              className={cn(
                "mt-4 font-serif text-4xl tracking-tight text-foreground opacity-0 md:text-5xl",
                isVisible && "animate-fade-in-up animation-delay-200"
              )}
            >
              <span className="text-balance">Featured Projects</span>
            </h2>
          </div>
          <Link
            href="/portfolio"
            className={cn(
              "inline-flex items-center text-sm font-medium tracking-wide text-primary opacity-0 transition-colors hover:text-accent",
              isVisible && "animate-fade-in-up animation-delay-400"
            )}
          >
            View All Projects
            <svg
              className="ml-2 h-4 w-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={1.5}
                d="M17 8l4 4m0 0l-4 4m4-4H3"
              />
            </svg>
          </Link>
        </div>

        <div className="mt-12 grid gap-6 md:grid-cols-2">
          {projects.map((project, index) => (
            <Link
              key={project.title}
              href={project.href}
              className={cn(
                "group relative aspect-[4/3] overflow-hidden opacity-0",
                isVisible && "animate-fade-in-up"
              )}
              style={{
                animationDelay: isVisible ? `${(index + 2) * 100}ms` : "0ms",
              }}
            >
              <Image
                src={project.image}
                alt={project.title}
                fill
                className="object-cover transition-transform duration-700 group-hover:scale-105"
                sizes="(max-width: 768px) 100vw, 50vw"
              />
              <div className="absolute inset-0 bg-foreground/0 transition-colors duration-500 group-hover:bg-foreground/40" />
              <div className="absolute inset-0 flex flex-col justify-end p-6 md:p-8">
                <div className="translate-y-4 opacity-0 transition-all duration-500 group-hover:translate-y-0 group-hover:opacity-100">
                  <span className="text-xs tracking-widest text-primary-foreground/70 uppercase">
                    {project.category}
                  </span>
                  <h3 className="mt-1 font-serif text-2xl text-primary-foreground md:text-3xl">
                    {project.title}
                  </h3>
                </div>
              </div>
            </Link>
          ))}
        </div>
      </div>
    </section>
  )
}
